#!/usr/bin/env python3
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
CONTACT=set('''POUND KARATE_CHOP DOUBLESLAP COMET_PUNCH MEGA_PUNCH FIRE_PUNCH ICE_PUNCH THUNDERPUNCH SCRATCH VICEGRIP GUILLOTINE CUT WING_ATTACK FLY BIND SLAM VINE_WHIP STOMP DOUBLE_KICK MEGA_KICK JUMP_KICK ROLLING_KICK SAND_ATTACK HEADBUTT HORN_ATTACK FURY_ATTACK HORN_DRILL TACKLE BODY_SLAM WRAP TAKE_DOWN THRASH DOUBLE_EDGE BITE PECK DRILL_PECK SUBMISSION LOW_KICK COUNTER SEISMIC_TOSS STRENGTH DIG QUICK_ATTACK RAGE LICK BIDE CLAMP SKULL_BASH CONSTRICT HI_JUMP_KICK LEECH_LIFE DIZZY_PUNCH CRABHAMMER FURY_SWIPES SLASH STRUGGLE MEGAHORN X_SCISSOR ASTONISH DRAIN_PUNCH STONE_PRESS FLAIL FACADE AERIAL_ACE LUNGE POISON_TAIL POISON_FANG WATERFALL TONGUE_LASH BRICK_BREAK FLAME_CHARGE AQUA_JET AMBUSH SHELL_BREAK TRIPLE_KICK CRUNCH OUTRAGE'''.split())
# Sand Attack is ranged; Counter/Bide are contact retaliation by design.
CONTACT.discard('SAND_ATTACK')
def render():
 rows=re.findall(r'^\s*move (\w+),\s*\w+,\s*(\d+),',(ROOT/'data/moves.asm').read_text(),re.M)
 return '; Generated by tools/generate_ability_moves.py. bit0 damage; bit1 contact.\nAbilityMoveMetadata:\n'+''.join(f'\tdb {int(int(power)>0)|(2 if name in CONTACT and int(power)>0 else 0)} ; {name}\n' for name,power in rows)
if __name__=='__main__':(ROOT/'data/ability_move_metadata.asm').write_text(render())
